/*
 * run_cases.c — Comprehensive Correctness Test Harness for SafeParse
 *
 * WHAT: Validates the correctness, memory safety, error handling, and
 *       equivalence of naive and optimized C parsers generated by SafeParse
 *       across three network and file format specifications:
 *       1. UDP Header (fixed header with dependent variable-length payload)
 *       2. PNG IHDR chunk (all fixed-size fields, bounds check merging)
 *       3. DNS Header (sequential 16-bit integer fields)
 *
 * WHY:  To demonstrate for academic evaluation and viva defense that:
 *       - Parsers correctly decode fields from valid input byte streams.
 *       - Bounds checks strictly prevent buffer over-reads on truncated data.
 *       - Semantic constraints (such as minimum UDP length) are properly enforced.
 *       - The bounds-check merging optimization preserves 100% behavioral
 *         equivalence with the unoptimized naive baseline (differential fuzzing).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stddef.h>

/*
 * Include both naive and optimized versions of each generated parser.
 * The headers define namespaced structs and functions (naive_* vs opt_*)
 * so that both implementations can be tested side-by-side in this binary.
 */
#include "udp_naive.h"
#include "udp_optimized.h"
#include "png_ihdr_naive.h"
#include "png_ihdr_optimized.h"
#include "dns_naive.h"
#include "dns_optimized.h"

/* Global test accounting counters */
static int g_tests_run = 0;
static int g_tests_passed = 0;
static int g_tests_failed = 0;

/*
 * record_test_result
 *
 * WHAT: Records the outcome of an individual test case, prints a formatted
 *       PASS or FAIL message to standard output, and increments counters.
 * WHY:  Centralizes test result logging so that the test harness produces
 *       consistent, human-readable output suitable for test logs and viva reviews.
 */
static void record_test_result(const char *test_description, int test_passed) {
    g_tests_run++;
    if (test_passed) {
        g_tests_passed++;
        printf("  [PASS] %s\n", test_description);
    } else {
        g_tests_failed++;
        printf("  [FAIL] %s\n", test_description);
    }
}

/*
 * test_valid_udp
 *
 * WHAT: Tests both naive and optimized UDP parsers against valid UDP datagrams:
 *       1. A datagram with an 8-byte header and a 5-byte payload ("HELLO").
 *       2. A datagram with an 8-byte header and a 0-byte (empty) payload.
 *       Asserts that both parsers return OK, all header fields match the input
 *       values, and the payload pointer and length are accurately set.
 * WHY:  Verifies fundamental parsing correctness for specifications containing
 *       dependent variable-length fields (where payload length is derived from
 *       a preceding header field: length - 8).
 */
static void test_valid_udp(void) {
    /* Test Case 1: UDP datagram with 5-byte payload "HELLO" */
    static const uint8_t udp_with_payload[13] = {
        0x30, 0x39,             /* src_port:  12345 (0x3039) */
        0x00, 0x50,             /* dst_port:  80 (0x0050) */
        0x00, 0x0D,             /* length:    13 bytes (8 header + 5 payload) */
        0xAB, 0xCD,             /* checksum:  0xABCD */
        'H', 'E', 'L', 'L', 'O' /* payload:   "HELLO" */
    };

    naive_UdpHeader naive_out;
    opt_UdpHeader opt_out;
    memset(&naive_out, 0, sizeof(naive_out));
    memset(&opt_out, 0, sizeof(opt_out));

    int naive_rc = naive_parse_UdpHeader(udp_with_payload, sizeof(udp_with_payload), &naive_out);
    int opt_rc = opt_parse_UdpHeader(udp_with_payload, sizeof(udp_with_payload), &opt_out);

    int udp1_passed = 1;
    if (naive_rc != NAIVE_PARSE_OK || opt_rc != OPT_PARSE_OK) {
        udp1_passed = 0;
    }
    if (naive_out.src_port != 12345 || opt_out.src_port != 12345) {
        udp1_passed = 0;
    }
    if (naive_out.dst_port != 80 || opt_out.dst_port != 80) {
        udp1_passed = 0;
    }
    if (naive_out.length != 13 || opt_out.length != 13) {
        udp1_passed = 0;
    }
    if (naive_out.checksum != 0xABCD || opt_out.checksum != 0xABCD) {
        udp1_passed = 0;
    }
    if (naive_out.payload_len != 5 || opt_out.payload_len != 5) {
        udp1_passed = 0;
    }
    if (naive_out.payload != (udp_with_payload + 8) || opt_out.payload != (udp_with_payload + 8)) {
        udp1_passed = 0;
    }
    if (memcmp(naive_out.payload, "HELLO", 5) != 0 || memcmp(opt_out.payload, "HELLO", 5) != 0) {
        udp1_passed = 0;
    }

    record_test_result("Valid UDP packet with 5-byte payload (port 12345->80, len 13)", udp1_passed);

    /* Test Case 2: UDP datagram with empty (0-byte) payload */
    static const uint8_t udp_empty_payload[8] = {
        0x00, 0x35, /* src_port: 53 (DNS) */
        0x00, 0x35, /* dst_port: 53 (DNS) */
        0x00, 0x08, /* length:   8 bytes (8 header + 0 payload) */
        0x00, 0x00  /* checksum: 0 */
    };

    memset(&naive_out, 0, sizeof(naive_out));
    memset(&opt_out, 0, sizeof(opt_out));

    naive_rc = naive_parse_UdpHeader(udp_empty_payload, sizeof(udp_empty_payload), &naive_out);
    opt_rc = opt_parse_UdpHeader(udp_empty_payload, sizeof(udp_empty_payload), &opt_out);

    int udp2_passed = 1;
    if (naive_rc != NAIVE_PARSE_OK || opt_rc != OPT_PARSE_OK) {
        udp2_passed = 0;
    }
    if (naive_out.src_port != 53 || opt_out.src_port != 53) {
        udp2_passed = 0;
    }
    if (naive_out.dst_port != 53 || opt_out.dst_port != 53) {
        udp2_passed = 0;
    }
    if (naive_out.length != 8 || opt_out.length != 8) {
        udp2_passed = 0;
    }
    if (naive_out.checksum != 0 || opt_out.checksum != 0) {
        udp2_passed = 0;
    }
    if (naive_out.payload_len != 0 || opt_out.payload_len != 0) {
        udp2_passed = 0;
    }
    if (naive_out.payload != (udp_empty_payload + 8) || opt_out.payload != (udp_empty_payload + 8)) {
        udp2_passed = 0;
    }

    record_test_result("Valid UDP packet with 0-byte payload (port 53->53, len 8)", udp2_passed);
}

/*
 * test_valid_png_ihdr
 *
 * WHAT: Tests both naive and optimized PNG IHDR chunk parsers against a valid
 *       13-byte IHDR structure representing a 1920x1080 8-bit RGBA image chunk.
 *       Asserts that both parsers return OK and all 7 fields match expected values.
 * WHY:  Validates parsing of mixed multi-byte (32-bit big-endian) and single-byte
 *       fields where the optimizer merges 7 separate bounds checks into 1 check.
 */
static void test_valid_png_ihdr(void) {
    static const uint8_t valid_ihdr_bytes[13] = {
        0x00, 0x00, 0x07, 0x80, /* width:              1920 (0x0780) */
        0x00, 0x00, 0x04, 0x38, /* height:             1080 (0x0438) */
        0x08,                   /* bit_depth:          8 */
        0x06,                   /* color_type:         6 (RGBA) */
        0x00,                   /* compression_method: 0 (deflate) */
        0x00,                   /* filter_method:      0 (adaptive) */
        0x00                    /* interlace_method:   0 (none) */
    };

    naive_PngIhdr naive_out;
    opt_PngIhdr opt_out;
    memset(&naive_out, 0, sizeof(naive_out));
    memset(&opt_out, 0, sizeof(opt_out));

    int naive_rc = naive_parse_PngIhdr(valid_ihdr_bytes, sizeof(valid_ihdr_bytes), &naive_out);
    int opt_rc = opt_parse_PngIhdr(valid_ihdr_bytes, sizeof(valid_ihdr_bytes), &opt_out);

    int passed = 1;
    if (naive_rc != NAIVE_PARSE_OK || opt_rc != OPT_PARSE_OK) {
        passed = 0;
    }
    if (naive_out.width != 1920 || opt_out.width != 1920) {
        passed = 0;
    }
    if (naive_out.height != 1080 || opt_out.height != 1080) {
        passed = 0;
    }
    if (naive_out.bit_depth != 8 || opt_out.bit_depth != 8) {
        passed = 0;
    }
    if (naive_out.color_type != 6 || opt_out.color_type != 6) {
        passed = 0;
    }
    if (naive_out.compression_method != 0 || opt_out.compression_method != 0) {
        passed = 0;
    }
    if (naive_out.filter_method != 0 || opt_out.filter_method != 0) {
        passed = 0;
    }
    if (naive_out.interlace_method != 0 || opt_out.interlace_method != 0) {
        passed = 0;
    }

    record_test_result("Valid PNG IHDR chunk (1920x1080, 8-bit RGBA, 13 bytes)", passed);
}

/*
 * test_valid_dns
 *
 * WHAT: Tests both naive and optimized DNS Header parsers against a valid
 *       12-byte standard DNS query header (ID 0x1234, standard query, 1 question).
 *       Asserts that both parsers return OK and all 6 16-bit fields are decoded accurately.
 * WHY:  Validates parsing of sequential fixed-width 16-bit big-endian integer fields
 *       and confirms that both parser variants extract every field identically.
 */
static void test_valid_dns(void) {
    static const uint8_t valid_dns_bytes[12] = {
        0x12, 0x34, /* id:      0x1234 */
        0x01, 0x00, /* flags:   0x0100 (standard query, recursion desired) */
        0x00, 0x01, /* qdcount: 1 question */
        0x00, 0x00, /* ancount: 0 answers */
        0x00, 0x00, /* nscount: 0 authority records */
        0x00, 0x00  /* arcount: 0 additional records */
    };

    naive_DnsHeader naive_out;
    opt_DnsHeader opt_out;
    memset(&naive_out, 0, sizeof(naive_out));
    memset(&opt_out, 0, sizeof(opt_out));

    int naive_rc = naive_parse_DnsHeader(valid_dns_bytes, sizeof(valid_dns_bytes), &naive_out);
    int opt_rc = opt_parse_DnsHeader(valid_dns_bytes, sizeof(valid_dns_bytes), &opt_out);

    int passed = 1;
    if (naive_rc != NAIVE_PARSE_OK || opt_rc != OPT_PARSE_OK) {
        passed = 0;
    }
    if (naive_out.id != 0x1234 || opt_out.id != 0x1234) {
        passed = 0;
    }
    if (naive_out.flags != 0x0100 || opt_out.flags != 0x0100) {
        passed = 0;
    }
    if (naive_out.qdcount != 1 || opt_out.qdcount != 1) {
        passed = 0;
    }
    if (naive_out.ancount != 0 || opt_out.ancount != 0) {
        passed = 0;
    }
    if (naive_out.nscount != 0 || opt_out.nscount != 0) {
        passed = 0;
    }
    if (naive_out.arcount != 0 || opt_out.arcount != 0) {
        passed = 0;
    }

    record_test_result("Valid DNS Header (id 0x1234, flags 0x0100, qdcount 1, 12 bytes)", passed);
}

/*
 * test_valid_packets
 *
 * WHAT: Coordinates the execution of all valid packet test cases across
 *       all three supported specifications (UDP, PNG IHDR, DNS Header).
 * WHY:  Serves as the high-level group function for positive test cases,
 *       ensuring basic parsing functionality before testing edge cases.
 */
static void test_valid_packets(void) {
    printf("\n--- Test Group 1: Valid Packet Parsing ---\n");
    test_valid_udp();
    test_valid_png_ihdr();
    test_valid_dns();
}

/*
 * test_truncation_udp
 *
 * WHAT: Takes a complete 13-byte UDP packet and systematically tests every prefix
 *       truncation from length 0 up to length 12 (full_length - 1).
 *       Verifies that both naive and optimized parsers reject the truncated
 *       input with ERR_TOO_SHORT (or ERR_BAD_LENGTH) and return matching error codes.
 * WHY:  Ensures memory safety by proving that partial packets cannot cause out-of-bounds
 *       memory reads during header parsing or payload slicing.
 */
static void test_truncation_udp(void) {
    static const uint8_t full_udp_packet[13] = {
        0x30, 0x39, 0x00, 0x50, 0x00, 0x0D, 0xAB, 0xCD,
        'H', 'E', 'L', 'L', 'O'
    };
    const size_t full_length = sizeof(full_udp_packet);

    for (size_t truncated_len = 0; truncated_len < full_length; truncated_len++) {
        naive_UdpHeader naive_out;
        opt_UdpHeader opt_out;
        memset(&naive_out, 0, sizeof(naive_out));
        memset(&opt_out, 0, sizeof(opt_out));

        int naive_rc = naive_parse_UdpHeader(full_udp_packet, truncated_len, &naive_out);
        int opt_rc = opt_parse_UdpHeader(full_udp_packet, truncated_len, &opt_out);

        /* Truncated buffer must return ERR_TOO_SHORT or ERR_BAD_LENGTH, not OK */
        int naive_rejected = (naive_rc == NAIVE_PARSE_ERR_TOO_SHORT || naive_rc == NAIVE_PARSE_ERR_BAD_LENGTH);
        int opt_rejected = (opt_rc == OPT_PARSE_ERR_TOO_SHORT || opt_rc == OPT_PARSE_ERR_BAD_LENGTH);
        int codes_match = (naive_rc == opt_rc);

        char description[128];
        snprintf(description, sizeof(description),
                 "UDP truncation at length %zu/%zu rejected (rc=%d)",
                 truncated_len, full_length, opt_rc);

        record_test_result(description, naive_rejected && opt_rejected && codes_match);
    }
}

